input.command:
dotnet build Atm/Atm.csproj --no-incremental 2>&1 | grep -E "warn|error|Warn" | head; mkdir -p /tmp/s/demo && cd /tmp/s/demo && cat > demo.csproj <<'EOF'
<Project Sdk="Microsoft.NET.Sdk">
  <PropertyGroup><OutputType>Exe</OutputType><TargetFramework>net10.0</TargetFramework><ImplicitUsings>enable</ImplicitUsings><Nullable>enable</Nullable></PropertyGroup>
  <ItemGroup><ProjectReference Include="/travail/Atm/Atm.csproj" /></ItemGroup>
</Project>
EOF
cat > Program.cs <<'EOF'
using Atm;
var d = new MoneyDispenser(new NoteCounts(0, 0, 0));
var m = new CashMachine(d);
Console.WriteLine(m.Execute(new AccountState(100, 0), new Operation.Deposit(new NoteCounts(1, 0, 0))));
Console.WriteLine($"stock={d.Stock}");
Console.WriteLine(m.Execute(new AccountState(150, 0), new Operation.Withdraw(50)) + "   (spec: Ok, 50x1)");
var d2 = new MoneyDispenser(new NoteCounts(1, 3, 0));
var m2 = new CashMachine(d2);
Console.WriteLine(m2.Execute(new AccountState(250, 0), new Operation.Withdraw(50)));
Console.WriteLine(m2.Execute(new AccountState(200, 50), new Operation.Withdraw(60)) + "   (spec: Ok, 20x3)");
EOF
dotnet run 2>&1 | tail -5

